      "arFull": "وَجَعَلْنَا مِنْ بَیْنِ اَیْدِیْهِمْ سَدًّا وَّمِنْ خَلْفِهِمْ سَدًّا فَاَغْشَیْنٰهُمْ فَهُمْ لَا یُبْصِرُوْنَ ۟",
