      "en": "And We have put before them a barrier and behind them a barrier and covered them, so they do not see.",
      "footnotesUr": "[1] یعنی دنیا کی زندگی ان کے لئے مزین کر دی گئی، یہ گویا ان کے سامنے کی آڑ ہے، جس کی وجہ سے وہ لذائذ دنیا کے علاوہ کچھ نہیں دیکھتے اور یہی چیز ان کے اور ایمان کے درمیان مانع اور حجاب ہے اور آخر کا تصور ان کے ذہنوں میں ناممکن الوقوع کردیا گیا، یہ گویا ان کے پیچھے کی آڑ ہے جس کی وجہ سے وہ توبہ کرتے ہیں نہ نصیحت حاصل کرتے ہیں، کیونکہ آخرت کا کوئی خوف ہی ان کے دلوں میں نہیں ہے۔\n[2] یا ان کی آنکھوں کو ڈھانک دیا یعنی رسول (صلى الله عليه وسلم) سے عداوت اور اس کی دعوت حق سے نفرت نے ان کی آنکھوں پر پٹی باندھ دی، یا انہیں اندھا کردیا ہے جس سے وہ دیکھ نہیں سکتے۔ یہ ان کے حال کی دوسری تمثیل ہے۔",
