      "en": "Indeed, I have believed in your Lord, so listen to me.\"",
      "footnotesUr": "[1] اس کی دعوت توحید اور اقرار توحید کے جواب میں قوم نے اسے قتل کرنا چاہا تو اس نے پیغمبروں سے خطاب کرکے یہ کہا، مقصد اپنے ایمان پر ان پیغمبروں کو گواہ بنانا تھا۔ یا اپنی قوم سے خطاب کرکے کہا جس سے مقصود دین حق پر اپنی صلابت اور استقامت کا اظہار تھا کہ تم جو چاہو کر لو، لیکن اچھی طرح سن لو کہ میرا ایمان اسی رب پر ہے، جو تمہارا بھی رب ہے۔ کہتے ہیں کہ انہوں نے اس کو مار ڈالا اور کسی نے ان کو اس سے نہیں روکا۔ رَحِمَهُ اللهُ تَعَالَى۔",
