      "footnotesUr": "[1] اس سے مراد ایسی سواریاں ہیں جو کشتی کی طرح انسانوں اور سامان تجارت کو ایک جگہ سے دوسری جگہ لے جاتی ہیں، اس میں قیامت تک پیدا ہونے والی چیزیں آگئیں۔ جیسے ہوائی جہاز، بحری جہاز، ریلیں، بسیں، کاریں اور دیگر نقل وحمل کی اشیا۔",
