      "arFull": "اَلْیَوْمَ نَخْتِمُ عَلٰۤی اَفْوَاهِهِمْ وَتُكَلِّمُنَاۤ اَیْدِیْهِمْ وَتَشْهَدُ اَرْجُلُهُمْ بِمَا كَانُوْا یَكْسِبُوْنَ ۟",
