      "arFull": "اَوَلَیْسَ الَّذِیْ خَلَقَ السَّمٰوٰتِ وَالْاَرْضَ بِقٰدِرٍ عَلٰۤی اَنْ یَّخْلُقَ مِثْلَهُمْ ؔؕ بَلٰی ۗ وَهُوَ الْخَلّٰقُ الْعَلِیْمُ ۟",
      "ur": "جس نے آسمانوں اور زمین کو پیدا کیا ہے کیا وه ان جیسوں[1] کے پیدا کرنے پرقادر نہیں، بےشک قادر ہے۔ اور وہی تو پیدا کرنے واﻻ دانا (بینا) ہے.",
